// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue, getResponseValue } from '@skyramp/skyramp';
import { createLink, getLink, deleteLink, deleteCollection } from './skyrampUtils';

// URL for test requests
const URL_localhost = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:3000");

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Definition of authentication header
    const headers: Record<string, string> = {};
    if (process.env.SKYRAMP_TEST_TOKEN && process.env.SKYRAMP_TEST_TOKEN != "") {
        headers["Authorization"] = "Bearer " + process.env.SKYRAMP_TEST_TOKEN;
    }

    // Request Body
    const linksPostRequestBody: string = `{
        "collection": {
            "name": "testbot-archive-status-error-col"
        },
        "name": "testbot-archive-status-error",
        "tags": [],
        "url": "http://127.0.0.1:9/testbot-archive-status-error"
    }`;

    const linksPostResponse = await createLink(client, URL_localhost, headers, linksPostRequestBody);
    expect(linksPostResponse.statusCode, 'status code').toBe(200);

    expect(getResponseValue(linksPostResponse, "response.name"), 'name').toBe("testbot-archive-status-error");
    expect(getResponseValue(linksPostResponse, "response.url"), 'url').toBe("http://127.0.0.1:9/testbot-archive-status-error");
    expect(getResponseValue(linksPostResponse, "response.type"), 'type').toBe("url");
    expect(getResponseValue(linksPostResponse, "response.collection.name"), 'collection name').toBe("testbot-archive-status-error-col");
    expect(getResponseValue(linksPostResponse, "response.id"), 'id').toBeGreaterThan(0);
    expect(getResponseValue(linksPostResponse, "response.collection.id"), 'collection id').toBeGreaterThan(0);

    const links999999GetResponse = await getLink(client, URL_localhost, headers, 999999, 401);
    expect(links999999GetResponse.statusCode, 'status code').toBe(401);

    expect(getResponseValue(links999999GetResponse, "response"), 'error body').toBe("Collection is not accessible.");
    expect(getResponseValue(links999999GetResponse, "response.archiveStatus"), 'error body carries no archiveStatus').toBeNull();
    expect(getResponseValue(links999999GetResponse, "response.id"), 'error body carries no link payload').toBeNull();

    const linksLinksDeleteResponse = await deleteLink(client, URL_localhost, headers, getResponseValue(linksPostResponse, "response.id"));
    expect(linksLinksDeleteResponse.statusCode, 'status code').toBe(200);

    expect(getResponseValue(linksLinksDeleteResponse, "response.id"), 'id').toBe(getResponseValue(linksPostResponse, "response.id"));
    expect(getResponseValue(linksLinksDeleteResponse, "response.name"), 'name').toBe("testbot-archive-status-error");

    const collectionsDeleteResponse = await deleteCollection(client, URL_localhost, headers, getResponseValue(linksPostResponse, "response.collection.id"));
    expect(collectionsDeleteResponse.statusCode, 'status code').toBe(200);

    expect(getResponseValue(collectionsDeleteResponse, "response.id"), 'id').toBe(getResponseValue(linksPostResponse, "response.collection.id"));
    expect(getResponseValue(collectionsDeleteResponse, "response.name"), 'collection name').toBe("testbot-archive-status-error-col");
});
